"""Generate docs/data/event-catalogue.md from the catalogue and the schemas.

The page is generated so it can never drift from the contracts: `make schemas-check` fails when the
committed page differs from what this module produces.
"""

from __future__ import annotations

import json
from pathlib import PurePosixPath
from typing import Any

from . import Paths
from .avsc import Sources, named_types, resolve
from .catalogue import KNOWN, Catalogue, Event, highest_privacy

HEADER = (
    "<!-- Generated by `make schemas-docs` from schemas/events/catalogue.yaml and the .avsc files."
    " Do not edit by hand: change the sources and regenerate. -->"
)
COMMON_RECORDS = ["Envelope", "ItemContext", "AccommodationContext", "Device"]


def cell(text: Any) -> str:
    return " ".join(str(text).split()).replace("|", "\\|")


def anchor(name: str) -> str:
    return name.lower().replace(".", "").replace("_", "-").replace(" ", "-")


def type_label(schema: Any, types: dict[str, dict]) -> str:
    if isinstance(schema, list):
        parts = [type_label(b, types) for b in schema if b != "null"]
        label = " or ".join(parts)
        return f"{label} or null" if "null" in schema else label
    if isinstance(schema, str) and schema in types:
        schema = types[schema]
    if isinstance(schema, str):
        return schema
    kind = schema.get("type")
    if "logicalType" in schema:
        return schema["logicalType"]
    if kind in ("record", "enum"):
        name = schema["name"].rsplit(".", 1)[-1]
        target = anchor(name) if name in COMMON_RECORDS else ("enums" if kind == "enum" else anchor(name))
        return f"[{name}](#{target})"
    if kind == "array":
        return f"array of {type_label(schema['items'], types)}"
    if kind == "map":
        return f"map of {type_label(schema['values'], types)}"
    return type_label(kind, types)


def default_label(field: dict) -> str:
    if "default" not in field:
        return "required"
    return f"`{json.dumps(field['default'])}`"


def fields_table(record: dict, types: dict[str, dict]) -> list[str]:
    lines = ["| Field | Type | Default | Class | Description |", "| --- | --- | --- | --- | --- |"]
    for f in record["fields"]:
        lines.append(
            f"| `{f['name']}` | {type_label(f['type'], types)} | {default_label(f)} | {f.get('privacy', '?')} |"
            f" {cell(f.get('doc', ''))} |"
        )
    return lines


def parties_table(parties: list[dict]) -> list[str]:
    lines = ["| Service | Tickets | Uses |", "| --- | --- | --- |"]
    for p in parties:
        lines.append(f"| {cell(p['service'])} | {', '.join(p['tickets'])} | {cell(p['uses'])} |")
    return lines


def event_section(event: Event, sources: Sources) -> list[str]:
    expanded = sources.expanded(event.name)
    types = named_types(expanded)
    retention = event.retention
    producer = event.producer
    required = ", ".join(f"`{n}`" for n in event.required_envelope) or "none (server event)"
    lines = [
        f"### {event.name}",
        "",
        cell(expanded["doc"]),
        "",
        f"- **Topic** `{event.topic}` · **subject** `{event.subject}` · **record** `kuizi.events.{expanded['name']}`",
        (
            f"- **Owner** {event.owner} · **producer** {cell(producer['service'])} ({', '.join(producer['tickets'])},"
            f" {producer['origin']} event)"
        ),
        f"- **Envelope fields that must be filled** {required}",
        (
            f"- **Retention** {retention['kafka_days']} days in Kafka,"
            f" {retention['warehouse_raw_months']} months raw in the warehouse"
            f" · **highest class** {highest_privacy(expanded)}"
        ),
        f"- **Example** [`schemas/events/{event.examples}`](../../schemas/events/{event.examples})",
        "",
        "Consumers (plus the [consumers of every event](#consumers-of-every-event)):",
        "",
        *parties_table(event.consumers),
        "",
    ]
    if event.sensitive_readers:
        lines += [
            "Allowed to read the sensitive fields (nobody else may read or store them):",
            "",
            *parties_table(event.sensitive_readers),
            "",
        ]
    lines += [*fields_table(expanded, types), ""]
    inline = [
        t
        for name, t in types.items()
        if t.get("type") == "record"
        and name.startswith("kuizi.events.")
        and not name.startswith("kuizi.events.common.")
        and t is not expanded
    ]
    for record in inline:
        lines += [f"#### {record['name']}", "", cell(record.get("doc", "")), "", *fields_table(record, types), ""]
    return lines


def render(catalogue: Catalogue, sources: Sources) -> str:
    raw = catalogue.raw
    privacy = catalogue.privacy
    lines = [
        HEADER,
        "",
        "# Learner event catalogue",
        "",
        (
            "Every learner interaction Kuizi records, as a versioned Avro event on the Kafka API (T023,"
            " [ADR 0010](../architecture/decisions/0010-learner-event-contracts.md)). This page is generated from"
            " [`schemas/events/catalogue.yaml`](../../schemas/events/catalogue.yaml) and the schemas next to it:"
            " change those, then run `make schemas-docs`. How to add or change an event:"
            " [`schemas/README.md`](../../schemas/README.md)."
        ),
        "",
        "## Conventions",
        "",
        "| Topic | Rule |",
        "| --- | --- |",
        (
            "| Format | Avro. One record per event; shared types in `schemas/events/common/` are inlined, so each"
            " registered schema is self-contained. |"
        ),
        (
            f"| Topics | `{raw['topic_prefix']}.<event>.v<major>`, one topic per event. A breaking change needs a new"
            " major (a new topic and subject) and a migration period. |"
        ),
        (
            "| Registry subjects | `<topic>-value` (topic name strategy)."
            f" Compatibility **{catalogue.compatibility}** on every subject,"
            " checked offline before merge and enforced by the registry. |"
        ),
        (
            f"| Kafka key | `{raw['key']}` as a plain UTF-8 string, so one learner's events stay in order in each"
            " topic. |"
        ),
        (
            "| De-duplication | `envelope.event_id`, a UUID (v7 recommended) created when the event happens; retries"
            " and offline replays reuse it. |"
        ),
        (
            "| Timestamps | UTC milliseconds since the epoch (`timestamp-millis`). `client_ts` is the device clock"
            " (used for elapsed and lag time), `server_ts` is set by Kuizi. |"
        ),
        (
            "| Identifiers | Pseudonymous UUIDs only. No name, email, phone number, national ID, IP address, device"
            " identifier, location, raw keystroke or free text. |"
        ),
        (
            "| Enums | First symbol `UNKNOWN`, which is also the enum default, so new values never break older"
            " readers. |"
        ),
        '| Optional fields | `["null", T]` with default `null`. Every field added later must have a default. |',
        (
            f"| Steward | The {raw['steward']} agent reviews every change; changing an event that other services"
            " read needs the product owner, and a new personal or sensitive field also needs the DPO. |"
        ),
        "",
        "## Privacy classes",
        "",
        f"Every field carries a `privacy` label in its schema. Rule followed: {cell(privacy['rule'])}",
        "",
        "| Class | Meaning | Who may read | Handling |",
        "| --- | --- | --- | --- |",
    ]
    for name, c in privacy["classes"].items():
        lines.append(f"| **{name}** | {cell(c['meaning'])} | {cell(c['readers'])} | {cell(c['handling'])} |")
    sensitive = ", ".join(f"`{r.rsplit('.', 1)[-1]}`" for r in catalogue.sensitive_records)
    forbidden = ", ".join(f"`{n}`" for n in sorted(catalogue.forbidden_names))
    lines += [
        "",
        (
            f"Sensitive fields may only live in {sensitive}; `make schemas-check` rejects a sensitive field anywhere"
            f" else. Field names that invite personal data are rejected too: {forbidden}."
        ),
        "",
        "## Events",
        "",
        "| Event | What it records | Owner | Producer | Highest class | Retention (Kafka / warehouse) |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for name, event in sorted(catalogue.events.items()):
        if name not in sources.events:
            continue
        r = event.retention
        lines.append(
            f"| [`{name}`](#{anchor(name)}) | {cell(event.description)} | {event.owner} |"
            f" {', '.join(event.producer['tickets'])} ({event.producer['origin']}) |"
            f" {highest_privacy(sources.expanded(name))} | {r['kafka_days']} d / {r['warehouse_raw_months']} mo |"
        )
    lines += [
        "",
        "## Knowledge-tracing inputs (for the ML sign-off)",
        "",
        (
            "What the knowledge-tracing models (ADR 0007: AKT proposed, DKT fallback, SAINT+ re-tested in T239) and"
            " the accommodation-aware work (T148) consume, and the event field that carries each input. Field"
            " references are checked against the schemas by `make schemas-check`."
        ),
        "",
        (
            "**Known** says when an input exists. Inputs known only after the answer feed the predictions of later"
            " attempts, never the prediction of the attempt they come from (shifted one step), so the label never"
            " leaks."
        ),
        "",
    ]
    if catalogue.ml_review:
        review = PurePosixPath(catalogue.ml_review).relative_to(PurePosixPath(Paths.DOC_REL).parent)
        lines += [
            (
                f"Reviewed by the ML Engineering agent: [ML review of the event schemas]({review}) (signed off with"
                " conditions, including rules for the tickets that build these features)."
            ),
            "",
        ]
    lines += ["| Model input | Models | Event fields | Known | Notes |", "| --- | --- | --- | --- | --- |"]
    for f in catalogue.ml_features:
        refs = "<br>".join(f"`{ref}`" for ref in f["fields"])
        known = KNOWN.get(f["known"], f["known"])
        lines.append(
            f"| {cell(f['feature'])} | {cell(', '.join(f['models']))} | {refs} | {known} | {cell(f['notes'])} |"
        )
    lines += ["", "## Event details", ""]
    for name, event in sorted(catalogue.events.items()):
        if name in sources.events:
            lines += event_section(event, sources)
    lines += [
        "## Shared records",
        "",
        "Defined once in `schemas/events/common/` and inlined into every event that uses them.",
        "",
    ]
    all_types: dict[str, dict] = {}
    for name in sorted(sources.events):
        all_types.update(named_types(sources.expanded(name)))
    for short in COMMON_RECORDS:
        record = resolve(f"kuizi.events.common.{short}", all_types)
        if isinstance(record, dict):
            lines += [f"### {short}", "", cell(record.get("doc", "")), "", *fields_table(record, all_types), ""]
    lines += ["### Enums", "", "| Enum | Symbols | Meaning |", "| --- | --- | --- |"]
    enums = sorted(((n.rsplit(".", 1)[-1], t) for n, t in all_types.items() if t.get("type") == "enum"))
    for short, enum in enums:
        lines.append(f"| `{short}` | {', '.join(f'`{s}`' for s in enum['symbols'])} | {cell(enum.get('doc', ''))} |")
    lines += ["", "## Consumers of every event", "", *parties_table(catalogue.common_consumers), ""]
    return "\n".join(lines)


def write_doc(paths: Paths, catalogue: Catalogue, sources: Sources) -> bool:
    """Write the page; returns True when it changed."""
    text = render(catalogue, sources)
    old = paths.doc.read_text(encoding="utf-8") if paths.doc.is_file() else None
    if old == text:
        return False
    paths.doc.parent.mkdir(parents=True, exist_ok=True)
    paths.doc.write_text(text, encoding="utf-8")
    return True


def doc_is_current(paths: Paths, catalogue: Catalogue, sources: Sources) -> bool:
    return paths.doc.is_file() and paths.doc.read_text(encoding="utf-8") == render(catalogue, sources)
